SELECT t1.id, t1.module_code, t1.module_name_en, t1.module_name_chn, t1.icon, t1.owned_enterprise_code, t1.module_state, t1.over_started, t1.remark, t1.update_time, t1.create_time, t1.delete_flag FROM dm_base.t_dm_base_module t1 WHERE t1.delete_flag = false
AND t1.owned_enterprise_code is null
AND t1.owned_enterprise_code is not null
AND t1.owned_enterprise_code = #{moduleFilterCondition.ownedEnterpriseCode}
AND t1.module_state = #{moduleFilterCondition.moduleState}
AND (t1.module_name_en LIKE '%'||#{moduleFilterCondition.moduleName}||'%' OR t1.module_name_chn LIKE '%'||#{moduleFilterCondition.moduleName}||'%')

SELECT t1.id, t1.module_code, t1.module_name_en, t1.module_name_chn, t1.icon, t1.owned_enterprise_code, t1.module_state, t1.over_started, t1.remark, t1.update_time, t1.create_time, t1.delete_flag FROM dm_base.t_dm_base_module t1 WHERE t1.module_code IN
#{moduleCode}
AND t1.delete_flag = false

