UPDATE dm_base.t_dm_base_module
SET
module_code = #{moduleUpdatePDTO.moduleCode}

    , module_name_chn = #{moduleUpdatePDTO.moduleNameChn}


    , icon = #{moduleUpdatePDTO.icon}


    , remark = #{moduleUpdatePDTO.remark}

WHERE module_code = #{moduleUpdatePDTO.moduleCode} AND delete_flag = false
